<script lang="ts">
 import { onMount } from 'svelte';
 import { uiLanguage, setUiLanguage } from './lib/i18n-core';
 import { getLiveStatusLabel } from './lib/session-labels';
 import { formatMinutes, scoreBand } from './lib/formatting';
 type Row=Record<string,any>; type Meeting=Record<string,any>;
 let page='live', connected=false, meeting:Meeting|null=null, record:any={rows:[],summary:{}}, meetings:Meeting[]=[], configs:any={}, filter='', mode='generic', stateRevision=0, stateValue:any={mode:'generic'}, configRevision:any={}, language='en';
 let recordSearch='', selectedRecords:string[]=[], configTab='roster', settings:any={};
 let activeFilter=''; let fileInput:HTMLInputElement;
 const t=(zh:string,en:string)=>language==='zh-CN'?zh:en;
 async function get(path:string){const r=await fetch(path);if(!r.ok)throw Error(`${r.status}`);return r.json()}
 async function refresh(){try{const s=await get('/api/meetings');meetings=s; if(meeting?.instanceId){record=await get(`/api/meetings/${meeting.instanceId}/record`)} else {meeting=meetings.find((m)=>!m.endedAt)||null;if(meeting)record=await get(`/api/meetings/${meeting.instanceId}/record`)}}catch{}}
 async function loadConfig(){for(const key of ['roster','aliases','profiles','settings']){try{const d=await get(`/api/config/${key}`);configs[key]=d.value;configRevision[key]=d.revision}catch{configs[key]=[]}}settings=configs.settings||{exportLanguage:'en',filterDefaultsClosed:false};}
 async function saveConfig(key:string,value:any){const r=await fetch(`/api/config/${key}`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({revision:configRevision[key]||0,value})});if(r.status===409){await loadConfig();throw Error(t('数据已被其他窗口修改，请重试。','Data changed in another window. Please retry.'))}if(!r.ok)throw Error(await r.text());const d=await r.json();configs[key]=d.value;configRevision[key]=d.revision}
 async function saveSettings(){try{await saveConfig('settings',settings)}catch(e:any){alert(e.message)}}
 function download(filename:string,data:string){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([data],{type:'application/json;charset=utf-8'}));a.download=filename;a.click();URL.revokeObjectURL(a.href)}
 async function downloadBackup(){const b=await get('/api/backup');download('attendflow-backup-v3.json',JSON.stringify(b,null,2))}
 async function exportRecords(ids:string[]=[]){const data=await get('/api/records/export');const records=(data.records||[]).filter((x:any)=>!ids.length||ids.includes(x.meeting.instanceId));download('attendflow-records.json',JSON.stringify({version:3,records},null,2))}
 async function deleteRecords(ids:string[]){if(!ids.length)return;const r=await fetch('/api/records/delete',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({instanceIds:ids})});if(!r.ok){alert(t('无法删除正在进行的会议。','Active meetings cannot be deleted.'));return}selectedRecords=[];meeting=null;await refresh()}
 async function addConfig(){let value:any={};if(configTab==='roster')value={personId:Date.now(),canonicalName:'',pinyin:'',group:'',active:true};if(configTab==='aliases')value={zoomName:'',personId:0};if(configTab==='profiles')value={id:`profile-${Date.now()}`,name:'',description:'',includedSubgroups:['*'],lateAfterMinutes:10,returnWindowMinutes:8,meetingIds:[],topicKeywords:[],groupSortOrder:[],active:true};const label=configTab==='roster'?'canonicalName':configTab==='aliases'?'zoomName':'name';const val=prompt(t('请输入名称','Enter name'));if(!val)return;value[label]=val;try{await saveConfig(configTab,[...(configs[configTab]||[]),value])}catch(e:any){alert(e.message)}}
 async function editConfig(index:number,item:any){const label=configTab==='roster'?'canonicalName':configTab==='aliases'?'zoomName':'name';const val=prompt(t('编辑名称','Edit name'),item[label]||'');if(val===null)return;const next=[...(configs[configTab]||[])];next[index]={...item,[label]:val};try{await saveConfig(configTab,next)}catch(e:any){alert(e.message)}}
 async function removeConfig(index:number){if(!confirm(t('确定删除此项目？','Delete this item?')))return;const next=[...(configs[configTab]||[])];next.splice(index,1);try{await saveConfig(configTab,next)}catch(e:any){alert(e.message)}}
 async function loadState(){if(!meeting)return;try{const d=await get(`/api/meetings/${meeting.instanceId}/state`);stateRevision=d.revision;stateValue=d.value;mode=d.value.mode||'generic'}catch{}}
 async function switchMode(next:string){if(!meeting)return;mode=next;stateValue={...stateValue,mode};try{const r=await fetch(`/api/meetings/${meeting.instanceId}/state`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({revision:stateRevision,value:stateValue})});if(r.status===409){await loadState();return}const d=await r.json();stateRevision=d.revision}catch{}}
 function summaryRows(key:string){activeFilter=key==='total'||activeFilter===key?'':key}
 $: rows=(record.rows||[]).filter((r:Row)=>{if(filter&&!`${r.canonicalName||''} ${r.zoomName||''}`.toLowerCase().includes(filter.toLowerCase()))return false;if(!activeFilter)return true;const tags=r.tags||[];return tags.includes(activeFilter)||({seen:r.hasBeenSeen,full_present:r.isCurrentlyPresent&&!r.wasLate,late:r.wasLate,returned:r.currentStatus==='returnedAfterLongAbsence',left_early:r.currentStatus==='leftEarly',missing:r.currentStatus==='missing',ignored:r.matchStatus==='guest'||r.matchStatus==='unmatched'} as any)[activeFilter]});
 onMount(()=>{language=localStorage.getItem('ui-language')||'en';const ws=new WebSocket(`ws://${location.host}/bridge`);ws.onopen=()=>{connected=true;ws.send(JSON.stringify({type:'subscribe'}))};ws.onclose=()=>connected=false;ws.onerror=()=>connected=false;ws.onmessage=(ev)=>{const m=JSON.parse(ev.data);if(m.type==='state'){meeting=m.meeting;refresh();loadState()}if(m.type==='record_updated'&&(!meeting||m.instanceId===meeting.instanceId)){refresh()}};refresh();loadConfig();return()=>ws.close()});
 async function importBackup(e:Event){const input=e.target as HTMLInputElement;const f=input.files?.[0];if(!f)return;try{const data=JSON.parse(await f.text());const preview=`${data.rosterPeople?.length||0} roster · ${data.aliasMappings?.length||0} aliases · ${data.attendanceProfiles?.length||0} profiles`;if(!confirm(`${t('将导入以下配置：','Import this backup configuration:')} ${preview}`))return;const r=await fetch('/api/backup',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});if(r.ok){await loadConfig();alert(t('备份配置已导入','Backup configuration imported'))}else alert(t('导入失败：','Import failed: ')+(await r.text()))}catch(err:any){alert(err.message)}finally{input.value=''}}
 function chooseLanguage(v:string){language=v;localStorage.setItem('ui-language',v);setUiLanguage(v as any)}
 const nav=[['live','◉','Live','实时'],['records','▤','Records','记录'],['configuration','⌘','Configuration','配置'],['settings','⚙','Settings','设置']];
 const stats=[['seen','Seen','到过'],['full_present','Full Present','全程到场'],['late','Late','迟到'],['returned','Returned','返回'],['left_early','Left Early','早退'],['missing','Absent','缺席'],['ignored','Ignored','不计入'],['total','Total','总计']];
</script>
<svelte:head><title>AttendFlow Desktop</title></svelte:head>
<div class="shell"><aside><div class="brand"><span class="mark">A</span><div><b>AttendFlow</b><small>DESKTOP</small></div></div><nav>{#each nav as [key,icon,en,zh]}<button class:active={page===key} onclick={()=>page=key}><span>{icon}</span>{t(zh,en)}</button>{/each}</nav><div class="connection"><i class:up={connected}></i>{connected?t('已连接','Connected'):t('正在连接','Connecting')}</div></aside><main><header><div><div class="eyebrow">{t('会议考勤','MEETING ATTENDANCE')}</div><h1>{page==='live'?t('实时会议','Live Meeting'):page==='records'?t('会议记录','Records'):page==='configuration'?t('配置','Configuration'):t('设置','Settings')}</h1></div><div class="header-actions">{#if meeting}<span class="live-pill"><i></i>{meeting.topic||meeting.meetingNumber||'Live meeting'}</span>{/if}<select value={language} onchange={(e)=>chooseLanguage(e.currentTarget.value)}><option value="en">English</option><option value="zh-CN">简体中文</option></select></div></header>
{#if page==='live'}
{#if meeting}<section class="meet-head"><div><b>{meeting.topic||t('未命名会议','Untitled meeting')}</b><small>{meeting.meetingNumber} · {new Date(meeting.startedAt).toLocaleString()}</small></div><div class="switch"><button class:chosen={mode==='generic'} onclick={()=>switchMode('generic')}>{t('通用','Generic')}</button><button class:chosen={mode==='roster'} onclick={()=>switchMode('roster')}>{t('花名册','Roster')}</button></div></section><section class="stats">{#each stats as [key,en,zh]}<button class:chosen={activeFilter===key} onclick={()=>summaryRows(key)}><small>{t(zh,en)}</small><strong>{key==='total'?record.summary?.total??0:record.summary?.[key==='full_present'?'fullPresent':key==='left_early'?'leftEarly':key]??0}</strong></button>{/each}</section><section class="toolbar"><input placeholder={t('搜索姓名…','Search names…')} bind:value={filter}/><span>{rows.length} {t('位参与者','participants')}</span></section><div class="table-wrap"><table><thead><tr><th>{t('姓名','Name')}</th><th>{t('Zoom 名称','Zoom name')}</th><th>{t('状态','Status')}</th><th>{t('位置','Location')}</th><th>{t('小组','Group')}</th><th>{t('首次加入','First join')}</th><th>{t('最近进出','Last seen')}</th><th>{t('分钟','Minutes')}</th>{#if meeting.isHost}<th>{t('等候室分钟','Waiting')}</th>{/if}</tr></thead><tbody>{#each rows as r}<tr><td><b>{r.canonicalName||r.zoomName}</b></td><td>{r.zoomName}</td><td><span class="chip">{getLiveStatusLabel(r.currentStatus,language as any)}</span></td><td>{r.currentLocation==='meeting'?t('会议中','In meeting'):r.currentLocation==='waiting-room'?t('等候室','Waiting room'):'—'}</td><td>{r.group||'—'}</td><td>{r.firstJoinAt?new Date(r.firstJoinAt).toLocaleTimeString():'—'}</td><td>{r.lastSeenAt?new Date(r.lastSeenAt).toLocaleTimeString():'—'}</td><td>{formatMinutes(r.totalPresenceMinutes)}</td>{#if meeting.isHost}<td>{Math.round(r.waitingRoomMinutes||0)}</td>{/if}</tr>{:else}<tr><td colspan="9" class="empty">{t('等待参与者事件…','Waiting for participant events…')}</td></tr>{/each}</tbody></table></div>{:else}<section class="empty-card"><span>◉</span><h2>{t('尚未加入会议','No active meeting')}</h2><p>{t('连接后，会议记录会自动显示在这里。','When you join a meeting, its attendance record will appear here.')}</p></section>{/if}
{:else if page==='records'}<div class="records-grid"><section class="panel"><h2>{t('所有会议','All meetings')} <small>{meetings.length}</small></h2><div class="toolbar"><input placeholder={t('按日期搜索 (YYYY-MM-DD)','Search date (YYYY-MM-DD)')} bind:value={recordSearch}/><button onclick={()=>exportRecords(selectedRecords)}>{t('导出所选/全部','Export selected/all')}</button><button class="danger" disabled={!selectedRecords.length} onclick={()=>deleteRecords(selectedRecords)}>{t('删除所选','Delete selected')}</button></div>{#each meetings.filter((m)=>!recordSearch||new Date(m.startedAt).toISOString().startsWith(recordSearch)) as m}<div class="meeting-row"><input type="checkbox" checked={selectedRecords.includes(m.instanceId)} onchange={(e)=>selectedRecords=e.currentTarget.checked?[...selectedRecords,m.instanceId]:selectedRecords.filter((id)=>id!==m.instanceId)}/><button class="meeting-pick" onclick={async()=>{meeting=m;record=await get(`/api/meetings/${m.instanceId}/record`);mode=record.mode||'generic';page='records'}}><span class="avatar">◷</span><span class="meeting-label"><b>{m.topic||m.meetingNumber}</b><small>{new Date(m.startedAt).toLocaleString()} · {m.isHost?t('主持人','Host'):t('参与者','Attendee')}</small></span><span class="score">{m.endedAt?t('已结束','Ended'):t('进行中','Live')}</span></button></div>{/each}</section>{#if meeting}<section class="panel"><h2>{meeting.topic||meeting.meetingNumber}</h2><div class="switch"><button class:chosen={mode==='generic'} onclick={()=>switchMode('generic')}>{t('通用','Generic')}</button><button class:chosen={mode==='roster'} onclick={()=>switchMode('roster')}>{t('花名册','Roster')}</button></div><p class="muted">{record.summary?.total??0} {t('位参与者','participants')}</p><div class="table-wrap"><table><thead><tr>{#if mode==='roster'}<th>{t('花名册姓名','Roster name')}</th><th>{t('Zoom 名称','Zoom name')}</th><th>{t('小组','Group')}</th>{:else}<th>{t('姓名','Name')}</th>{/if}<th>{t('状态','Status')}</th><th>{t('分数','Score')}</th><th>{t('出席分钟','Minutes')}</th></tr></thead><tbody>{#each record.rows||[] as r}<tr>{#if mode==='roster'}<td>{r.canonicalName||'—'}</td><td>{r.zoomName}</td><td>{r.group||'—'}</td>{:else}<td>{r.zoomName}</td>{/if}<td><span class="chip">{getLiveStatusLabel(r.currentStatus,language as any)}</span></td><td><span class="score" class:excellent={scoreBand(r.score)==='excellent'} class:good={scoreBand(r.score)==='good'} class:fair={scoreBand(r.score)==='fair'} class:low={scoreBand(r.score)==='low'} class:zero={scoreBand(r.score)==='zero'}>{Math.round(r.score||0)}%</span></td><td>{formatMinutes(r.totalPresenceMinutes)}</td></tr>{/each}</tbody></table></div></section>{/if}</div>
{:else if page==='configuration'}<section class="panel"><div class="panel-title"><div><h2>{t('AttendFlow 配置','AttendFlow configuration')}</h2><p>{t('管理花名册、名称匹配和考勤配置。','Manage roster, name matching, and attendance profiles.')}</p></div><div><button class="primary" onclick={addConfig}>＋ {t('新增','Add')}</button> <button onclick={()=>fileInput.click()}>{t('导入备份','Import backup')}</button></div><input bind:this={fileInput} type="file" accept="application/json,.json" hidden onchange={importBackup}/></div><div class="config-tabs">{#each [['roster','Roster','花名册'],['aliases','Aliases','名称匹配'],['profiles','Profiles','考勤配置']] as [key,en,zh]}<button class:chosen={configTab===key} onclick={()=>configTab=key}>{t(zh,en)} ({configs[key]?.length||0})</button>{/each}</div><div class="table-wrap"><table><thead><tr>{#each (configTab==='roster'?['ID','Canonical Name','Pinyin','Group','Active']:configTab==='aliases'?['Zoom Name','Person ID','Last Used']:['ID','Name','Groups','Active']) as h}<th>{h}</th>{/each}<th></th></tr></thead><tbody>{#each (configs[configTab]||[]) as item,i}<tr>{#if configTab==='roster'}<td>{item.personId??item.id}</td><td>{item.canonicalName}</td><td>{item.pinyin||'—'}</td><td>{item.group||'—'}</td><td>{item.active===false?'No':'Yes'}</td>{:else if configTab==='aliases'}<td>{item.zoomName||item.alias}</td><td>{item.personId}</td><td>{item.lastUsed||'—'}</td>{:else}<td>{item.id}</td><td>{item.name}</td><td>{(item.includedSubgroups||[]).join(', ')}</td><td>{item.active===false?'No':'Yes'}</td>{/if}<td><button onclick={()=>editConfig(i,item)}>{t('编辑','Edit')}</button> <button class="danger" onclick={()=>removeConfig(i)}>{t('删除','Delete')}</button></td></tr>{:else}<tr><td colspan="6" class="empty">{t('尚无数据','No data yet')}</td></tr>{/each}</tbody></table></div></section>
{:else}<section class="panel settings"><h2>{t('语言与界面','Language and display')}</h2><p>{t('界面语言与导出语言分别设置。','Set the interface and export language separately.')}</p><div class="language-options"><button class:chosen={language==='zh-CN'} onclick={()=>chooseLanguage('zh-CN')}>简体中文</button><button class:chosen={language==='en'} onclick={()=>chooseLanguage('en')}>English</button></div><label>{t('导出语言','Export language')} <select bind:value={settings.exportLanguage} onchange={saveSettings}><option value="en">English</option><option value="zh">简体中文</option></select></label><label>{t('大小','UI size')} <select value={localStorage.getItem('ui-size')||'medium'} onchange={(e)=>localStorage.setItem('ui-size',e.currentTarget.value)}><option value="compact">Compact</option><option value="medium">Medium</option><option value="large">Large</option><option value="xlarge">X Large</option><option value="xxlarge">XX Large</option></select></label><label><input type="checkbox" bind:checked={settings.filterDefaultsClosed} onchange={saveSettings}/> {t('默认折叠筛选器','Collapse filters by default')}</label><div class="settings-actions"><button onclick={downloadBackup}>{t('导出完整备份','Export full backup')}</button><button onclick={()=>fileInput.click()}>{t('恢复备份','Restore backup')}</button><button class="danger" onclick={async()=>{if(confirm(t('清除所有本地记录？','Clear all local records?'))){const r=await fetch('/api/local-data',{method:'DELETE'});if(r.ok){meeting=null;await refresh()}else alert(t('会议进行时不能清除数据。','Cannot clear while a meeting is live.'))}}}>{t('清除本地记录','Clear local records')}</button><input bind:this={fileInput} type="file" accept="application/json,.json" hidden onchange={importBackup}/></div><div class="about"><span class="mark">A</span><div><b>AttendFlow Desktop</b><small>Zoom Companion · Local-only attendance records</small></div></div></section>{/if}</main></div>






